 auto s=installed();auto ids=first_boot_chapter_ids(s);auto over=actor(-33,5);over.previous_feet={-33,6,3};(void)act(s,cmd(FirstBootChapterAction::arrive_hub),over);require(text(s,ids.progress,"first_route")=="alternative"&&!flag(s,ids.progress,"repair_used"),"over or around route remains alternative");
 s=installed();ids=first_boot_chapter_ids(s);repair(s);(void)act(s,cmd(FirstBootChapterAction::open_door,ids.main_door),actor(-33,2));auto air=actor(-33,5);air.previous_feet={-33,10,3};auto alternative=s;(void)act(alternative,cmd(FirstBootChapterAction::arrive_hub),air);require(text(alternative,ids.progress,"first_route")=="alternative"&&!flag(alternative,ids.progress,"repair_used"),"descending over open door is not a door route");rejects([&]{(void)first_boot_chapter_action(s,cmd(FirstBootChapterAction::close_door,ids.main_door),actor(-33,4));},"door cannot close into actor body");auto closure=*first_boot_chapter_action(s,cmd(FirstBootChapterAction::close_door,ids.main_door),actor(-33,2));rejects([&]{first_boot_chapter_rules(s,apply(s,closure),closure,actor(-33,4));},"SDK closure cannot bypass occupied-body validation");auto a=actor(-33,5);a.grounded=false;rejects([&]{(void)first_boot_chapter_action(s,cmd(FirstBootChapterAction::arrive_hub),a);},"arrival requires grounded body");
