void hazards_and_truth(){
 auto s=installed();auto ids=first_boot_chapter_ids(s);FirstBootChapterClock clock;auto sample=clock.sample(s);require(sample.phase==FirstBootArcPhase::telegraph&&sample.active_tick==0,"full initial warning");require(clock.advance(20,false)==0&&clock.tick()==0,"pause freezes clock");require(clock.advance(1)==8,"catchup bounded");for(int i=0;i<82;++i)clock.advance(1.0/60);sample=clock.sample(s);require(sample.phase==FirstBootArcPhase::arc&&clock.tick()==90,"90 tick telegraph");
 auto a=actor(-31.5f,-3);a.active_tick=clock.tick();a.hazard=sample;require(first_boot_chapter_hazard_contact(s,a),"actual arc contact");auto original=s;auto hit=*act(s,cmd(FirstBootChapterAction::recover_arc),a);require(count(s,ids.progress,"recoveries")==1,"atomic real recovery count");rejects([&]{(void)first_boot_chapter_action(s,cmd(FirstBootChapterAction::recover_arc),a);},"same recovery sample cannot be accepted as new operation twice");clock.acknowledge_recovery(sample);require(!clock.sample(s).recovery_available,"acknowledged cycle cannot repeat");
 for(int i=0;i<30;++i)clock.advance(1.0/60);require(clock.sample(s).phase==FirstBootArcPhase::cooldown,"30 tick arc");for(int i=0;i<120;++i)clock.advance(1.0/60);require(clock.sample(s).phase==FirstBootArcPhase::telegraph,"120 cooldown");for(int i=0;i<90;++i)clock.advance(1.0/60);auto newer=a;newer.active_tick=clock.tick();newer.hazard=clock.sample(s);(void)act(s,cmd(FirstBootChapterAction::recover_arc),newer);require(count(s,ids.progress,"recoveries")==2,"new cycle can produce one further actual recovery");rejects([&]{(void)first_boot_chapter_action(s,cmd(FirstBootChapterAction::recover_arc),a);},"older cycle cannot replay after a newer recovery");
 isolate(s,true);require(clock.sample(s).phase==FirstBootArcPhase::dormant,"isolation stops arcs");clock.advance(.1);isolate(s,false);auto reactivated=clock.sample(s);require(reactivated.phase==FirstBootArcPhase::telegraph&&reactivated.activation_tick==clock.tick()&&reactivated.activation_id!=sample.activation_id,"reactivation restarts warning and identity");FirstBootChapterClock restart;require(restart.sample(s).phase==FirstBootArcPhase::telegraph,"reload warning");require(first_boot_chapter_hazard_mesh(s,reactivated).vertices.size()==36&&first_boot_chapter_hazard_mesh(original,sample).vertices.size()==144,"bounded transient warning and arcs");
 auto bad=hit;std::get<HazardOutcome>(bad.events.back().payload).survived=true;rejects([&]{first_boot_chapter_rules(original,apply(original,bad),bad,a);},"cannot invent survival");auto candidate=installed();auto good=*first_boot_chapter_action(candidate,cmd(FirstBootChapterAction::inspect_fault),actor(-33,-4.3f));bad=good;std::get<MechanismOutcome>(bad.events[0].payload).before=true;rejects([&]{first_boot_chapter_rules(candidate,apply(candidate,bad),bad,actor(-33,-4.3f));},"false mechanism before rejected");bad=good;bad.deltas[0].component.fields["capacity"]=100.0;rejects([&]{first_boot_chapter_rules(candidate,apply(candidate,bad),bad,actor(-33,-4.3f));},"scan cannot secretly repair");bad=good;bad.deltas[0].component.fields["x"]=-32.0;rejects([&]{first_boot_chapter_rules(candidate,apply(candidate,bad),bad,actor(-33,-4.3f));},"immutable geometry protected");auto foreign=candidate;foreign.scope.branch_id="elsewhere";rejects([&]{first_boot_chapter_rules(candidate,foreign,good,actor(-33,-4.3f));},"foreign scope rejected");candidate.components.push_back(rec(candidate,first_boot_chapter_ids(candidate).fault));rejects([&]{first_boot_chapter_validate(candidate);},"duplicate identities rejected");
}
